import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import ContentArea from './components/ContentArea';

const API_URL = 'https://api.admin.u-code.io/v3/menus?parent_id=96ae1665-19fb-40c9-b5c6-e6fef7f538db&project-id=7380859b-8dac-4fe3-b7aa-1fdfcdb4f5c1';
const API_KEY = 'P-oyMjPNZutmtcfQSnv1Lf3K55J80CkqyP';

export default function App() {
  const [menus, setMenus] = useState([]);
  const [activeLabel, setActiveLabel] = useState('Dashboard');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMenus = async () => {
      try {
        const response = await axios.get(API_URL, {
          headers: {
            'Authorization': 'API-KEY',
            'X-API-KEY': API_KEY
          }
        });
        setMenus(response.data.menus || []);
      } catch (error) {
        console.error('Error fetching menu:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchMenus();
  }, []);

  return (
    <div className="flex h-screen bg-[#0a0a0a] text-zinc-300 font-sans">
      <Sidebar 
        menus={menus} 
        activeLabel={activeLabel} 
        setActiveLabel={setActiveLabel} 
        loading={loading} 
      />
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <Header activeLabel={activeLabel} />
        <ContentArea activeLabel={activeLabel} />
      </div>
    </div>
  );
}

import React from 'react';

export default function Sidebar({ menus, activeLabel, setActiveLabel, loading }) {
  return (
    <aside className="w-64 border-r border-zinc-800 bg-[#0f0f0f] flex flex-col">
      <div className="p-6 border-b border-zinc-800">
        <h1 className="text-white font-bold tracking-tight text-xl">CRM <span className="text-zinc-500 font-light">ADMIN</span></h1>
      </div>

      <nav className="flex-1 overflow-y-auto p-4 space-y-1">
        {loading ? (
          <div className="animate-pulse space-y-4 px-2">
            {[1, 2, 3, 4, 5].map(i => <div key={i} className="h-4 bg-zinc-800 rounded w-full"></div>)}
          </div>
        ) : (
          menus.map((menu) => (
            <button
              key={menu.id}
              onClick={() => setActiveLabel(menu.label)}
              className={`w-full text-left px-4 py-2.5 rounded-md text-sm transition-colors ${
                activeLabel === menu.label 
                ? 'bg-zinc-800 text-white font-medium' 
                : 'hover:bg-zinc-900 text-zinc-400 hover:text-zinc-200'
              }`}
            >
              {menu.label}
            </button>
          ))
        )}
      </nav>

      <div className="p-4 border-t border-zinc-800">
        <div className="flex items-center gap-3 px-2">
          <div className="w-8 h-8 rounded-full bg-zinc-700"></div>
          <div className="text-xs">
            <p className="text-white font-medium">Admin User</p>
            <p className="text-zinc-500">Enterprise Tier</p>
          </div>
        </div>
      </div>
    </aside>
  );
}

import React from 'react';

export default function Header({ activeLabel }) {
  return (
    <header className="h-16 border-b border-zinc-800 bg-[#0a0a0a] flex items-center justify-between px-8">
      <h2 className="text-sm font-medium text-zinc-400 uppercase tracking-widest">/ {activeLabel}</h2>
      <div className="flex gap-4">
        <div className="h-8 w-8 rounded bg-zinc-900 border border-zinc-800"></div>
        <div className="h-8 w-8 rounded bg-zinc-900 border border-zinc-800"></div>
      </div>
    </header>
  );
}

/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {
      fontFamily: {
        sans: ['Inter', 'system-ui', 'sans-serif'],
      },
    },
  },
  plugins: [],
}

